abstract class Formatter {
  abstract format(value: number): string;
  label(value: number): string { return `Значение: ${this.format(value)}`; }
}
class DecimalFormatter extends Formatter {
  format(value: number): string { return value.toFixed(2); }
}

interface Named { name: string }
class User implements Named { name = "гость"; }
class Admin extends User { role = "admin"; }
new Admin().name; // "гость": реальное наследование
// implements само по себе не создало бы name.

class Box<T> {
  constructor(public value: T) {}
  read(): T { return this.value; }
}
const box = new Box(42); // Box<number>
const value = box.read(); // number
// static defaultValue: T в таком классе не допускается.

class Base {
  format(value: string): string { return value }
}
class Trimmed extends Base {
  override format(value: string): string {
    return super.format(value).trim()
  }
}

class Query {
  where(_condition: string): this { return this }
}
class PagedQuery extends Query {
  limit(_count: number): this { return this }
}
new PagedQuery().where('active = true').limit(10)

